-- Generated by `yidam export --format warehouse` from this corpus's ontology. Regenerate rather than edit; an edited file is refused on the next export.
--
-- Feed `gcp-cai`: edge `attached-to` of class `compute-instance` into `edge_compute_instance__attached_to`.
-- Cloud Asset Inventory export, per-asset-type tables, daily.
-- Mode: snapshot: rows of this origin that landing no longer holds are deleted.
-- Parameters, to substitute before running (nothing else here is a template):
--   ${landing_dataset}  The dataset CAI exports into.
--   ${project}  The GCP project holding the landing dataset.
-- Run with the contract's dataset as the job's default dataset, as 0001_init.sql is.

DECLARE loaded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP();

CREATE TEMP TABLE _staged AS
SELECT DISTINCT * FROM (
SELECT
  CAST(name AS STRING) AS `src_id`,
  CAST(nic.network AS STRING) AS `dst_id`
FROM `${project}.${landing_dataset}.cai_compute_googleapis_com_Instance`,
  UNNEST(resource.data.networkInterfaces) AS nic
WHERE (resource.data.status != 'TERMINATED')
)
WHERE `src_id` IS NOT NULL AND `dst_id` IS NOT NULL;

MERGE `edge_compute_instance__attached_to` AS T
USING _staged AS S
ON T.`src_id` = S.`src_id` AND T.`dst_id` = S.`dst_id` AND T.`_origin` = "gcp-cai"
WHEN MATCHED THEN
  UPDATE SET `_loaded_at` = loaded_at, `_source` = "gcp-cloud-asset-inventory"
WHEN NOT MATCHED THEN
  INSERT (`src_id`, `dst_id`, `_origin`, `_loaded_at`, `_source`)
  VALUES (S.`src_id`, S.`dst_id`, "gcp-cai", loaded_at, "gcp-cloud-asset-inventory")
WHEN NOT MATCHED BY SOURCE AND T.`_origin` = "gcp-cai" THEN
  DELETE;
